756	//
757	
758	/// Lower tile.batch_matmul_acc into unrolled 2D tile.matmul_acc calls.
759	BatchMatmulAccResult LowerBatchMatmulAcc(const AssignStmtPtr& assign, const CallPtr& call,
760	                                         const std::vector<StmtPtr>& stmts, const FlattenContext& ctx,
761	                                         const OpRegistry& op_registry, const Span& span) {
762	  (void)assign;
763	  BatchMatmulAccResult out;
764	  auto def_map = BuildAssignDefMap(stmts);
765	
766	  // The acc operand has already been flattened (or is naturally 2D) by earlier
767	  // statement processing; substitute via var_map to pick up any rewrites.
768	  // Accept both Var and IterArg (loop-carried accumulator) — both are Var-like
769	  // in the IR and downstream code only needs name_hint_ + a stable Expr.
770	  auto acc_operand = Substitute(call->args_[0], ctx.var_map);
771	  auto acc_var = AsVarLike(acc_operand);
772	  CHECK(acc_var) << "FlattenTileNdTo2D: tile.batch_matmul_acc acc must be a Var/IterArg after "
773	                    "substitution, got "
774	                 << acc_operand->TypeName();
775	  auto acc_type = As<TileType>(acc_operand->GetType());
776	  CHECK(acc_type) << "FlattenTileNdTo2D: tile.batch_matmul_acc acc must be TileType";
777	  CHECK(acc_type->shape_.size() == 2)
778	      << "FlattenTileNdTo2D: tile.batch_matmul_acc expects acc to be 2D after flatten, got rank "
779	      << acc_type->shape_.size();
780	
781	  // The optional init_cond predicate is loop-invariant across the batch unroll:
782	  // each emitted tile.matmul_acc is the sole writer of its own row band of acc,
783	  // so "overwrite instead of accumulate" applies band by band. Forward it
